from export import ordered

class OrderTests(unittest.TestCase):
    def test_names(self):
        rows = [{"name": "Zoe"}, {"name": "amy"}]
        self.assertEqual([{"name": "amy"}, {"name": "Zoe"}], ordered(rows))

